from collections import defaultdict

owed_amounts = defaultdict(int)

for expense in parsed_expenses:
    paid_by = expense['paid_by']
    amount = expense['amount']
    owed_by = expense['owed_by']

    # Calculate the amount each person owes
    for person in owed_by:
        if ' and ' in person:
            # Split the person into individual names
            names = person.split(' and ')
            for name in names:
                owed_amounts[name] += amount / len(names)
        else:
            owed_amounts[person] += amount / len(owed_by)

print(owed_amounts)

